// Anmeldung (ALLY 36, Stefan 19.10.2026): eine Anmeldeseite für alle (K14); die Rolle steuert danach die Ansicht. Gleiche Sitzungen und Prüfungen wie ALLY 8
// (ally_web_login, ally_web_passwort_neu, ally_web_aktion 'passwort_setzen'). Passwörter verlassen den Browser nie im Klartext: gesendet wird nur
// SHA-256('ally-v2:' + Passwort), bei der Anmeldung zusätzlich das alte Verfahren (mit Benutzername) und der Startcode ('ally-code:' + Code) – wie ALLY 8.
// art 'seite' -> { html, set_cookie }, art 'aktion' -> { ziel, set_cookie } (303 im Eingang ALLY 20). Farben, Schrift und Logo nur aus CD 1.
// BA7 (Migration 62): auch Talents melden sich hier an (eigene Sitzung); ihr Zugangslink öffnet die Ansicht „neu“ mit code.einladung = true (Passwort zum ersten Mal festlegen).
// BA8 (Migration 63): „Passwort vergessen“ auf dieser Seite (Ansicht „vergessen“, Aktion vergessen), wenn ein Absender-Postfach eingestellt ist (vergessen_mail);
// sonst wie bisher der Link zur bisherigen Oberfläche (vergessen_adresse). Die Antwort verrät nie, ob es die Adresse gibt.
// Migration 209 (Fehler 46, Stefan 06.11.2026): Adressen ohne ?seite= – Seite und Objekt stehen im Pfad. Zuordnung aus der Datenbank (Tabelle ally_ui_pfade,
// Liste ally_ui_pfade_liste: m = Muster, s = Seitenschlüssel, f = feste Parameter, r = übrige Parameter als Abfrage). Gleiche Regeln wie ally_ui_pfad und die
// Web-App (webapp/src/pfade.ts): es zählt das Muster mit den meisten festen Parametern und Kennungen; Filter, Ansicht und Blättern stehen nicht im Pfad.
const PFAD_FREI = ['start', 'unbekannt', 'aktion', 'datei', 'manifest', 'symbol', 'kalender', 'stil', 'skript', 'logo', 'neu', 'api', 'mediakit', 'webhook'];
const PFAD_TEIL = v => encodeURIComponent(String(v)).replace(/%40/g, '@').replace(/%3A/g, ':');
const PFAD_FINDEN = (liste, seite, P0) => {
  const P = {};
  for (const k of Object.keys(P0 || {})) { const v = P0[k]; if (v !== undefined && v !== null && typeof v !== 'object' && String(v) !== '') P[k] = String(v); }
  let b = null, bs = -1;
  for (const r of Array.isArray(liste) ? liste : []) {
    if (!r || r.s !== seite || typeof r.m !== 'string') continue;
    const f = r.f && typeof r.f === 'object' ? r.f : {};
    if (Object.keys(f).some(k => P[k] !== String(f[k]))) continue;
    const ph = (r.m.match(/\{[a-z0-9_]+\}/g) || []).map(x => x.slice(1, -1));
    if (ph.some(k => !/^[^\/\x00-\x1f\x7f]{1,200}$/.test(P[k] || ''))) continue;
    const sc = Object.keys(f).length + ph.length;
    if (sc > bs) { b = r; bs = sc; }
  }
  if (!b) return { pfad: /^[a-z0-9-]{1,40}$/.test(String(seite)) && !PFAD_FREI.includes(seite) ? '/' + seite : '/', genutzt: [], rest: false };
  const ph = (b.m.match(/\{[a-z0-9_]+\}/g) || []).map(x => x.slice(1, -1));
  return { pfad: b.m.replace(/\{([a-z0-9_]+)\}/g, (_, k) => PFAD_TEIL(P[k])), genutzt: Object.keys(b.f || {}).concat(ph), rest: b.r === true };
};
const PFAD_BAUEN = (liste, seite, P) => {
  const x = PFAD_FINDEN(liste, seite, P);
  const rest = x.rest ? Object.keys(P || {}).filter(k => !x.genutzt.includes(k) && P[k] !== undefined && P[k] !== null && String(P[k]) !== '').sort() : [];
  return x.pfad + (rest.length ? '?' + rest.map(k => PFAD_TEIL(k) + '=' + PFAD_TEIL(P[k])).join('&') : '');
};
// bisherige Adresse „/?seite=…&…#anker“ (nur Basis /) als Pfad; die Meldung m bleibt als Abfrage. Ohne Zuordnung unverändert (ALLY 20 leitet dann um).
const ADRESSE_NEU = (liste, url) => {
  const m = String(url || '').match(/^\/\?([^#]*)(#.*)?$/);
  if (!m || !Array.isArray(liste) || !liste.length) return url;
  const q = new URLSearchParams(m[1]), P = {};
  q.forEach((v, k) => { if (k !== 'seite' && k !== 'm') P[k] = v; });
  const pfad = PFAD_BAUEN(liste, q.get('seite') || 'start', P), mm = q.get('m') || '';
  return pfad + (/^[a-z]{1,20}$/.test(mm) ? (pfad.includes('?') ? '&' : '?') + 'm=' + mm : '') + (m[2] || '');
};
const E = $('Start').first().json;
const Q = $input.first().json || {};
const BASIS = /^\/[A-Za-z0-9_\/-]*$/.test(String(E.basis || '')) && !String(E.basis).includes('//') ? String(E.basis) : '/webhook/app';
// BA11 (Migration 74): auf dem eigenen Host der Oberfläche (Basis /) ohne n8n-Sandbox SameSite=Lax; unter /webhook/app wie bisher None (Seite in der Sandbox)
const keks = (wert, alter) => 'ally_sitzung2=' + wert + '; Path=' + BASIS + '; Max-Age=' + alter + '; HttpOnly; Secure; SameSite=' + (BASIS === '/' ? 'Lax' : 'None');

if (E.art === 'aktion') {
  const r = Q.r || {};
  const zu = String(E.zurueck || '');
  // Migration 209 (Fehler 46, Stefan 06.11.2026): auf der eigenen Adresse auch ein Pfad (Seite und Objekt)
  const zurueck = zu === BASIS || zu.startsWith(BASIS + '?') || zu.startsWith(BASIS + '#')
    || (BASIS === '/' && /^\/[a-z0-9][A-Za-z0-9\/._~!*'()@:%-]{0,500}(\?[A-Za-z0-9&=%_.~-]{0,500})?$/.test(zu) && !zu.includes('//')) ? zu : BASIS;
  let ziel = BASIS, cookie = '';
  if (E.aktion === 'anmelden') {
    if (r.ok === true && /^[0-9a-f]{64}$/.test(String(r.token || ''))) { cookie = keks(r.token, Number(r.max_age) || 1800); ziel = r.muss_pw_setzen === true ? BASIS : zurueck; }
    else { ziel = BASIS + '?m=' + (r.code === 'gesperrt' ? 'gesperrt' : 'falsch'); cookie = keks('', 0); }
  } else if (E.aktion === 'passwort_neu') {
    if (r.ok === true && /^[0-9a-f]{64}$/.test(String(r.token || ''))) cookie = keks(r.token, Number(r.max_age) || 2592000);
    else ziel = r.code === 'passwort' && /^[0-9a-f]{64}$/.test(String(E.code || '')) ? ADRESSE_NEU(E.pfade, BASIS + '?seite=passwort-neu&code=' + E.code + '&m=pwfehler') : BASIS + '?m=link';
  } else if (E.aktion === 'vergessen') {
    ziel = BASIS + '?m=vergessen';
  } else if (E.aktion === 'passwort_setzen') {
    if (r.ungueltig === true) ziel = BASIS + '?m=ungueltig';
    else if (r.angemeldet === false) { ziel = BASIS + '?m=abgelaufen'; cookie = keks('', 0); }
    else if (/^[0-9a-f]{64}$/.test(String(E.sitzung || ''))) cookie = keks(E.sitzung, 2592000);
  } else ziel = BASIS + '?m=ungueltig';
  return [{ json: { ziel, set_cookie: cookie } }];
}

// ---------- Seiten: anmelden, festlegen (nach Startcode), neu (Link "Neues Passwort") ----------
const D = Q.a || {};
const CD = E.cd || {};
const F = CD.farben || {};
const farbe = n => /^#[0-9a-fA-F]{6}$/.test(String(F[n] || '')) ? String(F[n]) : null;
const FN = ['dunkel', 'textAufDunkel', 'akzent', 'akzentDunkel', 'hell', 'grau', 'warnung'];
for (const n of FN) if (!farbe(n)) throw new Error('Anmeldung: Corporate Design unvollständig (' + n + ').');
const schrift = /^[A-Za-z0-9 ]{1,60}$/.test(String(CD.schrift || '')) ? String(CD.schrift) : null;
if (!schrift) throw new Error('Anmeldung: Schrift im Corporate Design ungültig.');
const L = CD.logos || {};
const logo = typeof L.logo_fuer_dunkel === 'string' && /^data:image\/(svg\+xml|png);base64,[A-Za-z0-9+/]+={0,2}$/.test(L.logo_fuer_dunkel) ? L.logo_fuer_dunkel : null;
const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const PN = String(D.produkt || E.produkt || '').trim();
const AKTION = (BASIS === '/' ? '' : BASIS) + '/aktion';  // BA11: nie //aktion (Basis /)
const MELD = { falsch: ['E-Mail-Adresse oder Passwort stimmt nicht.', 'warn'], gesperrt: ['Zu viele Fehlversuche. Der Zugang ist für 15 Minuten gesperrt.', 'warn'],
  abgemeldet: ['Du bist abgemeldet.', 'ok'], abgelaufen: ['Bitte erneut anmelden.', 'warn'], ungueltig: ['Die Anfrage wurde abgelehnt. Bitte die Seite neu laden.', 'warn'],
  link: ['Der Link ist abgelaufen oder wurde schon benutzt. Bitte fordere einen neuen an.', 'warn'],
  pwfehler: ['Das Passwort konnte nicht gespeichert werden. Bitte noch einmal eingeben (mindestens 10 Zeichen, beide Felder gleich).', 'warn'],
  fehler: ['Die Anmeldung ist gerade nicht möglich. Bitte später noch einmal versuchen.', 'warn'],
  vergessen: ['Wenn die E-Mail-Adresse zu einem Zugang gehört, ist eine Mail mit einem Link unterwegs. Der Link gilt eine Stunde. Bitte auch im Spam-Ordner nachsehen.', 'ok'] };
const H0 = E.hinweis && typeof E.hinweis === 'object' && E.hinweis.text ? [String(E.hinweis.text), E.hinweis.ton === 'ok' ? 'ok' : 'warn'] : null;
const meld = MELD[E.meldung] || H0;
const box = meld ? '<div class="hinweis ' + meld[1] + '" role="' + (meld[1] === 'warn' ? 'alert' : 'status') + '">' + esc(meld[0]) + '</div>' : '';
const versteckt = (n, v) => '<input type="hidden" name="' + n + '" value="' + esc(v) + '">';
const pwFelder = '<label for="neu">Neues Passwort (mindestens 10 Zeichen)</label><input type="password" id="neu" data-feld="neu" autocomplete="new-password" required>' +
  '<label for="wiederholung">Neues Passwort wiederholen</label><input type="password" id="wiederholung" data-feld="wiederholung" autocomplete="new-password" required>' +
  '<p class="fehlertext" role="alert"></p>';
let titel, inhalt;
// BA8: Weg zu „Passwort vergessen“ – auf dieser Seite (Mail über das Absender-Postfach) oder wie bisher über die bisherige Oberfläche
const vergessenZiel = D.vergessen_mail === true ? ADRESSE_NEU(E.pfade, BASIS + '?seite=passwort-vergessen') : (D.vergessen_adresse || '');   // Migration 209 (Fehler 46, Stefan 06.11.2026)
if (E.ansicht === 'festlegen') {
  const P = E.person || {};
  titel = 'Passwort festlegen';
  inhalt = '<h1>' + titel + '</h1><p class="unter">Hallo ' + esc(P.name) + ', bitte lege jetzt dein eigenes Passwort fest.</p>' + box +
    '<form method="post" action="' + AKTION + '" data-pw="setzen">' + versteckt('aktion', 'passwort_setzen') + versteckt('csrf', E.csrf || '') + versteckt('zurueck', BASIS) +
    versteckt('neu', '') + versteckt('wiederholung', '') + versteckt('laenge', '') +
    '<input type="email" value="' + esc(P.email) + '" autocomplete="username" readonly hidden>' + pwFelder +
    '<button type="submit" class="knopf">Passwort speichern</button></form>';
} else if (E.ansicht === 'neu') {
  const C = D.code || {};
  titel = C.gueltig === true && C.einladung === true ? 'Zugang einrichten' : 'Neues Passwort';
  inhalt = C.gueltig === true
    ? '<h1>' + titel + '</h1><p class="unter">Hallo ' + esc(C.name) + (C.einladung === true ? ', lege hier dein Passwort für deinen Zugang fest.' : ', lege hier dein neues Passwort fest.') + '</p>' + box +
      '<form method="post" action="' + AKTION + '" data-pw="setzen">' + versteckt('aktion', 'passwort_neu') + versteckt('code', E.code || '') + versteckt('zurueck', BASIS) +
      versteckt('neu', '') + versteckt('wiederholung', '') + versteckt('laenge', '') +
      '<input type="email" value="' + esc(C.email) + '" autocomplete="username" readonly hidden>' + pwFelder +
      '<button type="submit" class="knopf">Passwort speichern</button></form>'
    : '<h1>' + titel + '</h1><div class="hinweis warn" role="alert">Der Link ist abgelaufen oder wurde schon benutzt. Ein Link „Neues Passwort“ gilt eine Stunde, ein Zugangslink bis zum angegebenen Datum, beide nur einmal. Einen neuen Zugangslink erstellt die zuständige Person.</div>' +
      (vergessenZiel ? '<p><a class="knopf neben" href="' + esc(vergessenZiel) + '">Neuen Link anfordern</a></p>' : '') + '<p><a href="' + esc(BASIS) + '">Zur Anmeldung</a></p>';
} else if (E.ansicht === 'vergessen') {
  titel = 'Passwort vergessen';
  inhalt = D.vergessen_mail === true
    ? '<h1>' + titel + '</h1><p class="unter">Gib die E-Mail-Adresse deines Zugangs ein. Du bekommst eine Mail mit einem Link, über den du ein neues Passwort festlegst.</p>' + box +
      '<form method="post" action="' + AKTION + '">' + versteckt('aktion', 'vergessen') + versteckt('zurueck', BASIS) +
      '<label for="email">E-Mail-Adresse</label><input type="email" id="email" name="email" autocomplete="username" autocapitalize="none" spellcheck="false" required>' +
      '<button type="submit" class="knopf">Link anfordern</button></form><p class="klein"><a href="' + esc(BASIS) + '">Zur Anmeldung</a></p>'
    : '<h1>' + titel + '</h1><p class="unter">Ein neues Passwort gibt es gerade nur über die zuständige Person' + (D.vergessen_adresse ? ' oder über den folgenden Link' : '') + '.</p>' +
      (D.vergessen_adresse ? '<p><a class="knopf neben" href="' + esc(D.vergessen_adresse) + '">Neues Passwort anfordern</a></p>' : '') + '<p><a href="' + esc(BASIS) + '">Zur Anmeldung</a></p>';
} else {
  titel = 'Anmeldung';
  inhalt = '<h1>' + titel + '</h1>' + box +
    '<form method="post" action="' + AKTION + '" data-pw="login">' + versteckt('aktion', 'anmelden') + versteckt('zurueck', E.zurueck || BASIS) +
    versteckt('h', '') + versteckt('ha', '') + versteckt('hc', '') +
    '<label for="benutzer">E-Mail-Adresse</label><input type="text" id="benutzer" name="benutzer" inputmode="email" autocomplete="username" autocapitalize="none" spellcheck="false" required>' +
    '<label for="pw">Passwort oder Startcode</label><input type="password" id="pw" data-feld="pw" autocomplete="current-password" required>' +
    '<p class="fehlertext" role="alert"></p><button type="submit" class="knopf">Anmelden</button></form>' +
    (vergessenZiel ? '<p class="klein"><a href="' + esc(vergessenZiel) + '">Passwort vergessen?</a></p>' : '');
}
const css = "@import url('https://fonts.googleapis.com/css2?family=" + encodeURIComponent(schrift).replace(/%20/g, '+') + ":wght@400;600;700&display=swap');" +
  ':root{--dunkel:' + farbe('dunkel') + ';--weiss:' + farbe('textAufDunkel') + ';--akzent:' + farbe('akzent') + ';--akzentDunkel:' + farbe('akzentDunkel') + ';--hell:' + farbe('hell') +
  ';--grau:' + farbe('grau') + ';--warn:' + farbe('warnung') + ";--flaeche:#FFFFFF;--schrift:'" + schrift + "'}" +
  '*{box-sizing:border-box}body{margin:0;background:var(--hell);color:var(--dunkel);font:15px/1.45 var(--schrift),"Helvetica Neue",Arial,sans-serif}' +
  '.kopf{height:64px;background:var(--dunkel);color:var(--weiss);display:flex;align-items:center;padding:0 20px}.kopf img{height:28px;display:block}.kopf b{font-size:18px}' +
  'main{max-width:440px;margin:40px auto;padding:0 16px}.karte{background:var(--flaeche);border:1px solid color-mix(in srgb,var(--dunkel) 12%,var(--hell));border-radius:12px;padding:24px}' +
  'h1{margin:0 0 6px;font-size:24px}.unter{margin:0 0 16px;color:var(--grau)}label{display:block;font-size:13px;font-weight:600;color:var(--grau);margin:14px 0 6px}' +
  'input:not([type=hidden]){width:100%;height:44px;border:1px solid color-mix(in srgb,var(--dunkel) 20%,var(--hell));border-radius:8px;padding:0 12px;font:500 15px var(--schrift),sans-serif;color:var(--dunkel);background:var(--flaeche)}' +
  '.knopf{display:inline-flex;align-items:center;justify-content:center;width:100%;height:44px;margin-top:18px;border:1px solid var(--dunkel);border-radius:8px;background:var(--dunkel);color:var(--weiss);font:600 15px var(--schrift),sans-serif;cursor:pointer;text-decoration:none}' +
  '.knopf.neben{background:var(--flaeche);color:var(--dunkel)}a{color:var(--akzentDunkel)}.klein{font-size:14px;margin:16px 0 0}' +
  ':focus-visible{outline:3px solid var(--akzentDunkel);outline-offset:2px}.fehlertext{color:var(--warn);font-weight:600;font-size:13px;min-height:1em;margin:8px 0 0}' +
  '.hinweis{border-radius:10px;padding:12px 14px;font-size:14px;margin:0 0 12px;border-left:4px solid var(--akzentDunkel);background:color-mix(in srgb,var(--akzent) 22%,var(--flaeche))}' +
  '.hinweis.warn{border-left-color:var(--warn);background:color-mix(in srgb,var(--warn) 10%,var(--flaeche))}';
const skript = "(function(){function sha(t){return crypto.subtle.digest('SHA-256',new TextEncoder().encode(t)).then(function(b){return Array.from(new Uint8Array(b)).map(function(x){return x.toString(16).padStart(2,'0');}).join('');});}" +
  "document.querySelectorAll('form[data-pw]').forEach(function(f){f.addEventListener('submit',function(e){if(f.dataset.fertig)return;e.preventDefault();" +
  "var fehler=f.querySelector('.fehlertext'),art=f.dataset.pw;function wert(n){return (f.querySelector('[data-feld='+n+']')||{}).value||'';}" +
  "function setze(n,v){f.querySelector('input[type=hidden][name='+n+']').value=v;}var p;" +
  "if(art==='login'){var u=((f.querySelector('[name=benutzer]')||{}).value||'').trim().toLowerCase(),pw=wert('pw');" +
  "p=Promise.all([sha('ally-v2:'+pw),sha('ally:'+u+':'+pw),sha('ally-code:'+pw.toUpperCase().replace(/[^A-Z0-9]/g,''))]).then(function(x){setze('h',x[0]);setze('ha',x[1]);setze('hc',x[2]);});}" +
  "else{var neu=wert('neu'),wdh=wert('wiederholung');if(neu.length<10){fehler.textContent='Das neue Passwort muss mindestens 10 Zeichen lang sein.';return;}" +
  "if(neu!==wdh){fehler.textContent='Die beiden neuen Passwörter stimmen nicht überein.';return;}" +
  "p=Promise.all([sha('ally-v2:'+neu),sha('ally-v2:'+wdh)]).then(function(x){setze('neu',x[0]);setze('wiederholung',x[1]);setze('laenge',String(neu.length));});}" +
  "p.then(function(){f.querySelectorAll('input[type=password]').forEach(function(i){i.value='';});f.dataset.fertig='1';f.submit();});});});})();";
// App-Symbol (Stefan 20.10.2026, 09:09): Manifest und Symbol aus ALLY 20 (GET <basis>/manifest, <basis>/symbol), auch auf der Anmeldeseite (Home-Bildschirm)
