const appKopf = '<link rel="manifest" href="' + esc(PFAD + '/manifest') + '"><link rel="icon" href="' + esc(PFAD + '/symbol') + '"><link rel="apple-touch-icon" href="' + esc(PFAD + '/symbol') + '">' +
  (PN ? '<meta name="apple-mobile-web-app-title" content="' + esc(PN) + '">' : '');
const html = '<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex, nofollow">' +
  '<title>' + esc([titel, PN].filter(Boolean).join(' – ')) + '</title>' + appKopf + '<style>' + css + '</style></head><body><header class="kopf">' +
  (logo ? '<img src="' + esc(logo) + '" alt="' + esc(PN) + '">' : '<b>' + esc(PN) + '</b>') + '</header><main><section class="karte">' + inhalt +
  '</section></main><script>' + skript + '</script></body></html>';
return [{ json: { html, set_cookie: String(E.set_cookie || '') } }];
